#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static size_t ilen = 0, ipos = 0;

static inline int gc() {
    if (ipos == ilen) {
        ilen = fread(ibuf, 1, sizeof ibuf, stdin);
        ipos = 0;
        if (ilen == 0) return -1;
    }
    return ibuf[ipos++];
}

static long long readInt() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    bool neg = c == '-';
    if (neg) c = gc();
    long long v = 0;
    while (c >= '0' && c <= '9') {
        v = v * 10 + (c - '0');
        c = gc();
    }
    return neg ? -v : v;
}

static string readToken() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    string s;
    while (c > ' ') {
        s.push_back((char)c);
        c = gc();
    }
    return s;
}

int main() {
    int n = (int)readInt();
    vector<string> names(n);
    for (auto &s : names) s = readToken();
    vector<string> order = names;
    sort(order.begin(), order.end());
    unordered_map<string, int> rank;
    rank.reserve(n * 2);
    for (int i = 0; i < n; i++) rank[order[i]] = i;
    int m = (int)readInt();
    vector<vector<int>> g(n);
    vector<int> indeg(n, 0);
    for (int i = 0; i < m; i++) {
        string a = readToken(), b = readToken();
        int x = rank[a], y = rank[b];
        g[y].push_back(x);  // y must be compiled before x
        indeg[x]++;
    }
    priority_queue<int, vector<int>, greater<int>> h;
    for (int i = 0; i < n; i++)
        if (indeg[i] == 0) h.push(i);
    vector<int> out;
    while (!h.empty()) {
        int x = h.top();
        h.pop();
        out.push_back(x);
        for (int y : g[x])
            if (--indeg[y] == 0) h.push(y);
    }
    if ((int)out.size() != n) {
        puts("IMPOSSIBLE");
        return 0;
    }
    string res;
    for (int i = 0; i < n; i++) {
        if (i) res.push_back(' ');
        res += order[out[i]];
    }
    puts(res.c_str());
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        String[] order = new String[n];
        for (int i = 0; i < n; i++) order[i] = next();
        Arrays.sort(order);
        HashMap<String, Integer> rank = new HashMap<>(n * 2);
        for (int i = 0; i < n; i++) rank.put(order[i], i);
        int m = nextInt();
        int[] from = new int[m], to = new int[m], indeg = new int[n], start = new int[n + 1];
        for (int i = 0; i < m; i++) {
            int x = rank.get(next()), y = rank.get(next());
            from[i] = y; // y must be compiled before x
            to[i] = x;
            indeg[x]++;
            start[y + 1]++;
        }
        for (int i = 0; i < n; i++) start[i + 1] += start[i];
        int[] adj = new int[m], fill = Arrays.copyOf(start, n);
        for (int i = 0; i < m; i++) adj[fill[from[i]]++] = to[i];
        PriorityQueue<Integer> h = new PriorityQueue<>();
        for (int i = 0; i < n; i++) if (indeg[i] == 0) h.add(i);
        int[] out = new int[n];
        int cnt = 0;
        while (!h.isEmpty()) {
            int x = h.poll();
            out[cnt++] = x;
            for (int e = start[x]; e < start[x + 1]; e++) if (--indeg[adj[e]] == 0) h.add(adj[e]);
        }
        if (cnt != n) {
            System.out.println("IMPOSSIBLE");
            return;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            sb.append(order[out[i]]);
        }
        System.out.println(sb);
    }
}

package main

import (
	"container/heap"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

type intHeap []int

func (h intHeap) Len() int           { return len(h) }
func (h intHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h intHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *intHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *intHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	order := make([]string, n)
	for i := range order {
		order[i] = string(token())
	}
	sort.Strings(order)
	rank := make(map[string]int, n)
	for i, s := range order {
		rank[s] = i
	}
	m := nextInt()
	g := make([][]int, n)
	indeg := make([]int, n)
	for i := 0; i < m; i++ {
		x := rank[string(token())]
		y := rank[string(token())]
		g[y] = append(g[y], x) // y must be compiled before x
		indeg[x]++
	}
	h := &intHeap{}
	for i := 0; i < n; i++ {
		if indeg[i] == 0 {
			*h = append(*h, i)
		}
	}
	out := make([]string, 0, n)
	for h.Len() > 0 {
		x := heap.Pop(h).(int)
		out = append(out, order[x])
		for _, y := range g[x] {
			indeg[y]--
			if indeg[y] == 0 {
				heap.Push(h, y)
			}
		}
	}
	if len(out) != n {
		fmt.Println("IMPOSSIBLE")
		return
	}
	fmt.Println(strings.Join(out, " "))
}
